// Top-K (K = 2048) selection of the largest FP32 scores per row.
//
// Row -> top-K pipeline, three launches:
//
//   values[B,S] --hist(top byte)--> bucket b1 --hist(2nd byte)--> cutoff filter
//                 (64 blocks)                       (64 blocks)
//   --gather(key >= filter)--> candidates --radix select + bitonic sort--> out
//        (32 blocks)                          (last block only)
//
// The two histogram passes shrink the candidate set to the cutoff bucket, so the
// final single block only ever touches roughly K + bucket elements.
#include <torch/extension.h>
#include <c10/cuda/CUDAGuard.h>
#include <c10/cuda/CUDAStream.h>
#include <cuda_runtime.h>

namespace {

constexpr int kK = 2048;  // top-k width, const K of the problem definition
constexpr int kBinBits = 8;
constexpr int kBins = 1 << kBinBits;
constexpr int kMask = kBins - 1;
constexpr int kHistBlocks = 64;
constexpr int kHistThreads = 256;
constexpr int kGatherBlocks = 32;
constexpr int kFinalThreads = 1024;
constexpr unsigned int kKeyMax = 0xFFFFFFFFu;

// Candidate pair: monotonic key plus its index inside the row.
struct __align__(8) Pair {
  unsigned int key;
  unsigned int idx;
};

// Per-row cross-launch state.
struct __align__(16) RowSel {
  unsigned int filter;  // gathered candidates satisfy key >= filter
  int need;             // elements still required inside the level-1 bucket
  int cand_n;           // gather counter, reset before the next call
  int pad;
};

// Order-preserving float -> unsigned key map (bigger key == bigger float).
__device__ __forceinline__ unsigned int mono_key(float value) {
  const unsigned int bits = __float_as_uint(value);
  return (bits & 0x80000000u) ? ~bits : (bits | 0x80000000u);
}

__device__ __forceinline__ float key_to_float(unsigned int key) {
  const unsigned int bits = (key & 0x80000000u) ? (key & 0x7fffffffu) : ~key;
  return __uint_as_float(bits);
}

// Locate the bucket holding the rank-th largest element (1-based rank) and count
// the elements strictly above it. Threads [0, kBins) drive the scan; every thread
// in the block must reach the barriers, so the guards stay inside the loop body.
__device__ void locate_bucket(const int* __restrict__ hist, int rank, int* __restrict__ suff,
                              int* __restrict__ digit_out, int* __restrict__ above_out) {
  const int tid = threadIdx.x;

  // Reversed inclusive scan: suff[i] = sum of hist over buckets [kBins-1-i, kBins).
  if (tid < kBins) suff[tid] = hist[kBins - 1 - tid];
  __syncthreads();
  for (int step = 1; step < kBins; step <<= 1) {
    int value = 0;
    int add = 0;
    if (tid < kBins) {
      value = suff[tid];
      if (tid >= step) add = suff[tid - step];
    }
    __syncthreads();
    if (tid < kBins) suff[tid] = value + add;
    __syncthreads();
  }

  // Lowest index whose suffix sum reaches the rank marks the bucket.
  const bool hit = (tid < kBins) && (suff[tid] >= rank);
  const unsigned int ballot = __ballot_sync(0xFFFFFFFFu, hit);
  __shared__ int s_first[kBins / 32];
  if ((tid & 31) == 0 && (tid >> 5) < kBins / 32)
    s_first[tid >> 5] = (ballot "'!= 0) ? (__ffs(ballot) - 1) : -1;
  __syncthreads();
  if (tid == 0) {
    int first = -1;
    for (int warp = 0; warp < kBins / 32; ++warp) {
      if (s_first[warp] >= 0) {
        first = warp * 32 + s_first[warp];
        break;
      }
    }
    *digit_out = kBins - 1 - first;
    *above_out = (first > 0) ? suff[first - 1] : 0;
  }
  __syncthreads();
}

// Byte-level histogram pass. LEVEL 1 histograms the top key byte of the whole row;
// LEVEL 2 histograms the second byte of the level-1 bucket only. The last block to
// finish reduces the per-block slices and records the cutoff for the next stage.
template <int LEVEL>
__global__ void hist_pass(const float* __restrict__ values, int s, int chunk,
                          unsigned int* __restrict__ slices, RowSel* __restrict__ rows,
                          int* __restrict__ tickets) {
  __shared__ int bins[kBins];
  __shared__ bool is_last;
  __shared__ int suff[kBins];

  for (int i = threadIdx.x; i < kBins; i += blockDim.x) bins[i] = 0;
  __syncthreads();

  const int row = blockIdx.y;
  const float* row_in = values + (size_t)row * s;
  RowSel* sel = rows + row;
  const int begin = blockIdx.x * chunk;
  const int end = min(begin + chunk, s);

  if (LEVEL == 1) {
    for (int i = begin + threadIdx.x; i < end; i += blockDim.x)
      atomicAdd(&bins[mono_key(row_in[i]) >> 24], 1);
  } else {
    const unsigned int prefix = sel->filter >> 16;  // level-1 bucket prefix
    for (int i = begin + threadIdx.x; i < end; i += blockDim.x) {
      const unsigned int key = mono_key(row_in[i]);
      if ((key >> 16) == prefix) atomicAdd(&bins[(key >> 8) & kMask], 1);
    }
  }
  __syncthreads();

  unsigned int* slice = slices + ((size_t)row * gridDim.x + blockIdx.x) * kBins;
  for (int i = threadIdx.x; i < kBins; i += blockDim.x) slice[i] = (unsigned int)bins[i];
  __threadfence();
  if (threadIdx.x == 0) is_last = (atomicAdd(tickets + row, 1) == (int)gridDim.x - 1);
  __syncthreads();
  if (!is_last) return;
  __threadfence();

  // Reduce the per-block slices into the block-private histogram.
  for (int i = threadIdx.x; i < kBins; i += blockDim.x) bins[i] = 0;
  __syncthreads();
  for (unsigned int b = 0; b < gridDim.x; ++b) {
    const unsigned int* other = slices + ((size_t)row * gridDim.x + b) * kBins;
    for (int i = threadIdx.x; i < kBins; i += blockDim.x) bins[i] += (int)other[i];
  }
  __syncthreads();

  const int rank = (LEVEL == 1) ? kK : sel->need;
  int digit = 0;
  int above = 0;
  locate_bucket(bins, rank, suff, &digit, &above);

  if (threadIdx.x == 0) {
    if (LEVEL == 1) {
      sel->filter = (unsigned int)digit << 24;
      sel->need = kK - above;
    } else {
      sel->filter |= (unsigned int)digit << 16;
      sel->cand_n = 0;
    }
    tickets[row] = 0;  // ready for the next call
  }
}

// Ascending bitonic sort of `span` (power of two) key/index pairs.
__device__ void bitonic_asc(Pair* __restrict__ pairs, int span) {
  for (int size = 2; size <= span; size <<= 1) {
    for (int stride = size >> 1; stride > 0; stride >>= 1) {
      for (int i = threadIdx.x; i < span; i += blockDim.x) {
        const int other = i ''^ stride;
        if (other <= i) continue;
        const bool ascending = (i & size) == 0;
        const Pair a = pairs[i];
        const Pair b = pairs[other];
        if ((a.key > b.key) == ascending) {
          pairs[i] = b;
          pairs[other] = a;
        }
      }
      __syncthreads();
    }
  }
}

// Exact top-K of the gathered candidates: radix select the K-th largest key, then
// order the strictly larger keys and append the ties of the K-th key.
__device__ void select_final(const Pair* __restrict__ cand, int n, float* __restrict__ out_values,
                             long long* __restrict__ out_idx, int* __restrict__ s_hist,
                             int* __restrict__ s_suff, Pair* __restrict__ s_above,
                             unsigned int* __restrict__ s_eq) {
  const int tid = threadIdx.x;
  __shared__ int s_cnt[2];

  unsigned int prefix = 0;
  int rank = kK;
  for (int shift = 24; shift >= 0; shift -= kBinBits) {
    for (int i = tid; i < kBins; i += blockDim.x) s_hist[i] = 0;
    __syncthreads();
    for (int i = tid; i < n; i += blockDim.x) {
      const unsigned int key = cand[i].key;
      const bool active = (shift == 24) || ((key >> (shift + kBinBits)) == prefix);
      if (active) atomicAdd(&s_hist[(key >> shift) & kMask], 1);
    }
    __syncthreads();
    int digit = 0;
    int above = 0;
    locate_bucket(s_hist, rank, s_suff, &digit, &above);
    rank -= above;
    prefix = (prefix << kBinBits) | (unsigned int)digit;
  }
  const unsigned int kth = prefix;

  if (tid < 2) s_cnt[tid] = 0;
  __syncthreads();
  for (int i = tid; i < n; i += blockDim.x) {
    const unsigned int key = cand[i].key;
    if (key > kth) {
      const int slot = atomicAdd(&s_cnt[0], 1);
      if (slot < kK) {
        s_above[slot].key = key;
        s_above[slot].idx = cand[i].idx;
      }
    } else if (key == kth) {
      const int slot = atomicAdd(&s_cnt[1], 1);
      if (slot < kK) s_eq[slot] = cand[i].idx;
    }
  }
  __syncthreads();
  const int n_above = min(s_cnt[0], kK);

  // Ascending sort with maximum-key padding; the real entries end up at the tail.
  int span = 1;
  while (span < n_above) span <<= 1;
  for (int i = tid; i < span; i += blockDim.x) {
    if (i >= n_above) s_above[i].key = kKeyMax;
  }
  __syncthreads();
  bitonic_asc(s_above, span);
  __syncthreads();

  for (int i = tid; i < n_above; i += blockDim.x) {
    const Pair p = s_above[span - 1 - i];
    out_values[i] = key_to_float(p.key);
    out_idx[i] = (long long)p.idx;
  }
  const int fill = kK - n_above;
  for (int i = tid; i < fill; i += blockDim.x) {
    out_values[n_above + i] = key_to_float(kth);
    out_idx[n_above + i] = (long long)s_eq[i];
  }
}

// Gather candidates (key >= filter) and finish the selection in the last block.
__global__ void gather_pass(const float* __restrict__ values, int s, int chunk,
                            Pair* __restrict__ cand, RowSel* __restrict__ rows,
                            float* __restrict__ out_values, long long* __restrict__ out_idx,
                            int* __restrict__ tickets) {
  __shared__ int s_hist[kBins];
  __shared__ int s_suff[kBins];
  __shared__ Pair s_above[kK];
  __shared__ unsigned int s_eq[kK];
  __shared__ bool is_last;

  const int row = blockIdx.y;
  RowSel* sel = rows + row;
  const float* row_in = values + (size_t)row * s;
  Pair* row_cand = cand + (size_t)row * s;
  const int begin = blockIdx.x * chunk;
  const int end = min(begin + chunk, s);
  const int total = end - begin;
  const int lane = threadIdx.x & 31;
  const unsigned int filter = sel->filter;
  const int iterations = (total + blockDim.x - 1) / blockDim.x;

  for (int it = 0; it < iterations; ++it) {
    const int j = it * blockDim.x + threadIdx.x;
    const bool active = j < total;
    unsigned int key = 0;
    if (active) key = mono_key(row_in[begin + j]);
    const bool take = active && (key >= filter);
    const unsigned int mask = __ballot_sync(0xFFFFFFFFu, take);
    int base = 0;
    if (lane == 0) base = atomicAdd(&sel->cand_n, __popc(mask));
    base = __shfl_sync(0xFFFFFFFFu, base, 0);
    if (take) {
      const int slot = base + __popc(mask & ((1u << lane) - 1u));
      row_cand[slot].key = key;
      row_cand[slot].idx = (unsigned int)(begin + j);
    }
  }

  __threadfence();
  if (threadIdx.x == 0) is_last = (atomicAdd(tickets + row, 1) == (int)gridDim.x - 1);
  __syncthreads();
  if (!is_last) return;
  __threadfence();

  const int n = sel->cand_n;
  select_final(row_cand, n, out_values + (size_t)row * kK,
               out_idx + (size_t)row * kK, s_hist, s_suff, s_above, s_eq);
  if (threadIdx.x == 0) {
    sel->cand_n = 0;
    tickets[row] = 0;
  }
}

// ---------------------------------------------------------------------------
// Host side
// ---------------------------------------------------------------------------

void check_inputs(const torch::Tensor& values, const torch::Tensor& top_values,
                  const torch::Tensor& indices) {
  TORCH_CHECK_VALUE(values.is_cuda(), "values must be a CUDA tensor");
  TORCH_CHECK_TYPE(values.scalar_type() == torch::kFloat32, "values must be float32");
  TORCH_CHECK_VALUE(values.dim() == 2, "values must have shape [B, S]");
  TORCH_CHECK_VALUE(values.is_contiguous(), "values must be contiguous");

  TORCH_CHECK_VALUE(top_values.is_cuda(), "top_values must be a CUDA tensor");
  TORCH_CHECK_TYPE(top_values.scalar_type() == torch::kFloat32, "top_values must be float32");
  TORCH_CHECK_VALUE(top_values.is_contiguous(), "top_values must be contiguous");
  TORCH_CHECK_TYPE(indices.scalar_type() == torch::kInt64, "indices must be int64");
  TORCH_CHECK_VALUE(indices.is_contiguous(), "indices must be contiguous");

  const int64_t rows = values.size(0);
  const int64_t s = values.size(1);
  TORCH_CHECK_VALUE(s >= kK, "sequence length must be at least K");
  TORCH_CHECK_VALUE(top_values.dim() == 2 && top_values.size(0) == rows &&
                        top_values.size(1) == kK,
                    "top_values must have shape [B, K]");
  TORCH_CHECK_VALUE(indices.dim() == 2 && indices.size(0) == rows && indices.size(1) == kK,
                    "indices must have shape [B, K]");
  TORCH_CHECK_VALUE(top_values.device() == values.device() && indices.device() == values.device(),
                    "device mismatch");
  TORCH_CHECK_VALUE(s <= INT32_MAX, "sequence length too large");
  TORCH_CHECK_VALUE(rows <= INT32_MAX, "batch too large");
}

// Persistent workspace: the kernels keep it zeroed across calls, so the steady
// state costs no allocation and no memset.
torch::Tensor& scratch(int device, int64_t rows, int64_t s) {
  static torch::Tensor buffer;
  static int64_t cached_rows = -1;
  static int64_t cached_s = -1;
  static int cached_device = -1;
  if (!buffer.defined() || cached_rows != rows || cached_s != s || cached_device != device) {
    const int64_t words = 2 * rows * kHistBlocks * kBins + rows * 4 + 2 * rows * s + 3 * rows;
    buffer = torch::zeros({words}, torch::TensorOptions().dtype(torch::kInt32).device(
                                       torch::Device(torch::kCUDA, device)));
    cached_rows = rows;
    cached_s = s;
    cached_device = device;
  }
  return buffer;
}

void kernel(const torch::Tensor& values, const torch::Tensor& top_values,
            const torch::Tensor& indices) {
  check_inputs(values, top_values, indices);
  const int64_t rows = values.size(0);
  const int64_t s = values.size(1);
  if (rows == 0) return;

  c10::cuda::CUDAGuard guard(values.device());
  const cudaStream_t stream = c10::cuda::getCurrentCUDAStream(values.get_device()).stream();
  torch::Tensor& workspace = scratch(values.get_device(), rows, s);

  unsigned int* words = reinterpret_cast<unsigned int*>(workspace.data_ptr<int>());
  const size_t slices_per_row = (size_t)kHistBlocks * kBins;
  unsigned int* hist1 = words;
  unsigned int* hist2 = hist1 + (size_t)rows * slices_per_row;
  RowSel* rows_sel = reinterpret_cast<RowSel*>(hist2 + (size_t)rows * slices_per_row);
  Pair* cand = reinterpret_cast<Pair*>(rows_sel + rows);
  int* tickets = reinterpret_cast<int*>(cand + (size_t)rows * s);

  const int hist_chunk = (int)((s + kHistBlocks - 1) / kHistBlocks);
  const int gather_chunk = (int)((s + kGatherBlocks - 1) / kGatherBlocks);
  const dim3 hist_grid(kHistBlocks, (unsigned int)rows);
  const dim3 gather_grid(kGatherBlocks, (unsigned int)rows);

  const float* in = values.data_ptr<float>();
  float* out_values = top_values.data_ptr<float>();
  long long* out_idx = reinterpret_cast<long long*>(indices.data_ptr<int64_t>());

  hist_pass<1><<<hist_grid, kHistThreads, 0, stream>>>(in, (int)s, hist_chunk, hist1, rows_sel,
                                                       tickets);
  hist_pass<2><<<hist_grid, kHistThreads, 0, stream>>>(in, (int)s, hist_chunk, hist2, rows_sel,
                                                       tickets + rows);
  gather_pass<<<gather_grid, kFinalThreads, 0, stream>>>(in, (int)s, gather_chunk, cand, rows_sel,
                                                         out_values, out_idx, tickets + 2 * rows);

  const cudaError_t error = cudaGetLastError();
  TORCH_CHECK(error == cudaSuccess, "topk launch failed: ", cudaGetErrorString(error));
}

}  // namespace

PYBIND11_MODULE(TORCH_EXTENSION_NAME, module) {
  module.def("kernel", &kernel);
}
