// Top-K (K = 2048) selection of the largest FP32 scores per row.
//
//   values[B,S]
//     |-- hist byte3 --|  last block: bucket b1 + count above it
//     |-- hist byte2 --|  restricted to bucket b1 -> cutoff byte p2
//     |-- hist byte1 --|  restricted to (b1,p2)  -> cutoff byte p3 (8-bit aligned key)
//     |-- scatter    --|  keys >= filter+256 fill [0,def) ; bucket keys fill [def,K)
//
// The cutoff is exact to 24 key bits, so every element strictly above the cutoff
// is selected and any need = K-def elements of the cutoff bucket are equally
// valid: the surviving spread is below 2"'^-15 relative, far inside the 1e-2
// tolerance. Each pass is a single streaming read of the row.
#include <torch/extension.h>
#include <c10/cuda/CUDAGuard.h>
#include <c10/cuda/CUDAStream.h>
#include <cuda_runtime.h>

namespace {

constexpr int kK = 2048;  // top-k width, const K of the problem definition
constexpr int kBinBits = 8;
constexpr int kBins = 1 << kBinBits;
constexpr int kMask = kBins - 1;
constexpr int kHistBlocks = 64;
constexpr int kHistThreads = 256;
constexpr int kGatherBlocks = 64;
constexpr int kGatherThreads = 512;
constexpr int kMaxWarps = kGatherThreads / 32;
constexpr unsigned int kKeyMax = 0xFFFFFFFFu;
constexpr unsigned int kNoBin = 0xFFFFFFFFu;

// Per-row cross-launch state.
struct __align__(16) RowSel {
  unsigned int filter;  // cutoff key, low 8 bits cleared
  int need;             // elements still required inside the cutoff bucket
  int reserve_hi;       // scatter reservations for keys >= filter + kBins
  int reserve_lo;       // scatter reservations inside the cutoff bucket
};

// Order-preserving float -> unsigned key map (bigger key == bigger float).
__device__ __forceinline__ unsigned int mono_key(float value) {
  const unsigned int bits = __float_as_uint(value);
  return (bits & 0x80000000u) ? ~bits : (bits | 0x80000000u);
}

__device__ __forceinline__ float key_to_float(unsigned int key) {
  const unsigned int bits = (key & 0x80000000u) ? (key & 0x7fffffffu) : ~key;
  return __uint_as_float(bits);
}

// Locate the bucket holding the rank-th largest element (1-based rank) and count
// the elements strictly above it. Results land in shared out[0]=digit, out[1]=above
// because every thread needs them. Threads [0, kBins) drive the scan; every thread
// must reach the barriers, so the guards stay inside the loop bodies.
__device__ void locate_bucket(const int* __restrict__ hist, int rank, int* __restrict__ suff,
                              int* __restrict__ out) {
  const int tid = threadIdx.x;

  // Reversed inclusive scan: suff[i] = sum of hist over buckets [kBins-1-i, kBins).
  if (tid < kBins) suff[tid] = hist[kBins - 1 - tid];
  __syncthreads();
  for (int step = 1; step < kBins; step <<= 1) {
    int value = 0;
    int add = 0;
    if (tid < kBins) {
      value = suff[tid];
      if (tid >= step) add = suff[tid - step];
    }
    __syncthreads();
    if (tid < kBins) suff[tid] = value + add;
    __syncthreads();
  }

  // Lowest index whose suffix sum reaches the rank marks the bucket.
  const bool hit = (tid < kBins) && (suff[tid] >= rank);
  const unsigned int ballot = __ballot_sync(0xFFFFFFFFu, hit);
  __shared__ int s_first[kBins / 32];
  if ((tid & 31) == 0 && (tid >> 5) < kBins / 32)
    s_first[tid >> 5] = (ballot != 0) ? (__ffs(ballot) - 1) : -1;
  __syncthreads();
  if (tid == 0) {
    int first = -1;
    for (int warp = 0; warp < kBins / 32; ++warp) {
      if (s_first[warp] >= 0) {
        first = warp * 32 + s_first[warp];
        break;
      }
    }
    out[0] = (first >= 0) ? (kBins - 1 - first) : 0;
    out[1] = (first > 0) ? suff[first - 1] : 0;
  }
  __syncthreads();
}

// One byte of the key per pass. LEVEL 1 histograms byte3 of the whole row, LEVEL 2
// byte2 inside bucket byte3, LEVEL 3 byte1 inside bucket (byte3,byte2). The last
// block to finish reduces the per-block slices and advances the cutoff.
template <int LEVEL>
__global__ void hist_pass(const float* __restrict__ values, int s, int chunk,
                          unsigned int* __restrict__ slices, RowSel* __restrict__ rows,
                          int* __restrict__ tickets) {
  __shared__ int bins[kBins];
  __shared__ int nz_bin[kBins];
  __shared__ int suff[kBins];
  __shared__ int s_locate[2];
  __shared__ int s_nz;
  __shared__ bool is_last;

  for (int i = threadIdx.x; i < kBins; i += blockDim.x) bins[i] = 0;
  if (threadIdx.x == 0) s_nz = 0;
  __syncthreads();

  const int row = blockIdx.y;
  const float* row_in = values + (size_t)row * s;
  RowSel* sel = rows + row;
  const int begin = blockIdx.x * chunk;
  const int end = min(begin + chunk, s);
  const int count = end - begin;
  const int shift = (LEVEL == 1) ? 24 : (LEVEL == 2) ? 16 : 8;
  const int upper = shift + kBinBits;
  const unsigned int prefix = (LEVEL == 1) ? 0u : (sel->filter >> upper);
  const unsigned int lane = threadIdx.x & 31u;
  const int iterations = (count + blockDim.x - 1) / blockDim.x;

  // One shared atomic per distinct bin in a warp: clustered scores would otherwise
  // serialise 32 ways on the same address.
  for (int it = 0; it < iterations; ++it) {
    const int j = it * blockDim.x + threadIdx.x;
    unsigned int bin = kNoBin;
    if (j < count) {
      const unsigned int key = mono_key(row_in[begin + j]);
      if (LEVEL == 1 || ((key >> upper) == prefix)) bin = (key >> shift) & kMask;
    }
    const unsigned int match = __match_any_sync(0xFFFFFFFFu, bin);
    if (bin < kBins && (match & ((1u << lane) - 1u)) == 0) atomicAdd(&bins[bin], __popc(match));
  }
  __syncthreads();

  // Compacted flush: only non-empty bins travel to global memory.
  if (threadIdx.x < kBins && bins[threadIdx.x] != 0) {
    const int slot = atomicAdd(&s_nz, 1);
    nz_bin[slot] = threadIdx.x;
  }
  __syncthreads();
  unsigned int* slice = slices + ((size_t)row * gridDim.x + blockIdx.x) * (1 + 2 * kBins);
  if (threadIdx.x == 0) slice[0] = (unsigned int)s_nz;
  for (int i = threadIdx.x; i < s_nz; i += blockDim.x) {
    const int bin = nz_bin[i];
    slice[1 + 2 * i] = (unsigned int)bin;
    slice[2 + 2 * i] = (unsigned int)bins[bin];
  }
  __threadfence();
  __syncthreads();
  if (threadIdx.x == 0) is_last = (atomicAdd(tickets + row, 1) == (int)gridDim.x - 1);
  __syncthreads();
  if (!is_last) return;
  __threadfence();

  // Last block: rebuild the row histogram and advance the cutoff.
  for (int i = threadIdx.x; i < kBins; i += blockDim.x) bins[i] = 0;
  __syncthreads();
  for (int b = threadIdx.x; b < (int)gridDim.x; b += blockDim.x) {
    const unsigned int* other = slices + ((size_t)row * gridDim.x + b) * (1 + 2 * kBins);
    for (unsigned int i = 0; i < other[0]; ++i)
      atomicAdd(&bins[other[1 + 2 * i]], (int)other[2 + 2 * i]);
  }
  __syncthreads();

  const int rank = (LEVEL == 1) ? kK : sel->need;
  locate_bucket(bins, rank, suff, s_locate);

  if (threadIdx.x == 0) {
    sel->filter |= (unsigned int)s_locate[0] << shift;
    sel->need = (LEVEL == 1) ? (kK - s_locate[1]) : (sel->need - s_locate[1]);
    if (LEVEL == 3) {
      sel->reserve_hi = 0;
      sel->reserve_lo = 0;
    }
    tickets[row] = 0;  // ready for the next call
  }
}

// Scatter: keys at or above the cutoff bucket (exact cutoff to 24 key bits) fill
// the tail of the row; everything above fills the head. Any need of the tail
// elements are interchangeable, so no ordering pass is required.
__global__ void gather_pass(const float* __restrict__ values, int s, int chunk,
                            RowSel* __restrict__ rows, float* __restrict__ out_values,
                            long long* __restrict__ out_idx) {
  __shared__ int s_warp_cnt[2][kMaxWarps];
  __shared__ int s_warp_off[2][kMaxWarps];
  __shared__ int s_res[2];

  const int row = blockIdx.y;
  RowSel* sel = rows + row;
  const unsigned int filter = sel->filter;
  const unsigned int hi = (filter <= kKeyMax - kBins) ? (filter + kBins) : kKeyMax;
  const int head = kK - sel->need;  // slots for keys >= hi
  const float* row_in = values + (size_t)row * s;
  float* out_v = out_values + (size_t)row * kK;
  long long* out_i = out_idx + (size_t)row * kK;
  const int begin = blockIdx.x * chunk;
  const int end = min(begin + chunk, s);
  const int count = end - begin;
  const int lane = threadIdx.x & 31u;
  const int warp = threadIdx.x >> 5;
  const int iterations = (count + blockDim.x - 1) / blockDim.x;

  // Pass 1: count this block'"'s output slots so one reservation per region suffices.
  int cnt_hi = 0;
  int cnt_lo = 0;
  for (int it = 0; it < iterations; ++it) {
    const int j = it * blockDim.x + threadIdx.x;
    unsigned int key = 0;
    if (j < count) key = mono_key(row_in[begin + j]);
    const bool top = (j < count) && (key >= hi);
    const bool bucket = (j < count) && (key >= filter) && (key < hi);
    cnt_hi += __popc(__ballot_sync(0xFFFFFFFFu, top));
    cnt_lo += __popc(__ballot_sync(0xFFFFFFFFu, bucket));
  }
  if (lane == 0) {
    s_warp_cnt[0][warp] = cnt_hi;
    s_warp_cnt[1][warp] = cnt_lo;
  }
  __syncthreads();
  if (threadIdx.x == 0) {
    int off_hi = 0;
    int off_lo = 0;
    for (int w = 0; w < kMaxWarps; ++w) {
