  1	// Top-K (K = 2048) selection of the largest FP32 scores per row.
  2	//
  3	//   values[B,S]
  4	//     |-- hist byte3 --|  last block: bucket b1 + count above it
  5	//     |-- hist byte2 --|  restricted to bucket b1 -> cutoff byte p2
  6	//     |-- hist byte1 --|  restricted to (b1,p2)  -> cutoff byte p3 (8-bit aligned key)
  7	//     |-- scatter    --|  keys >= filter+256 fill [0,def) ; bucket keys fill [def,K)
  8	//
  9	// The cutoff is exact to 24 key bits, so every element strictly above the cutoff
 10	// is selected and any need = K-def elements of the cutoff bucket are equally
 11	// valid: the surviving spread is below 2^-15 relative, far inside the 1e-2
 12	// tolerance. Each pass is a single streaming read of the row.
 13	#include <torch/extension.h>
 14	#include <c10/cuda/CUDAGuard.h>
 15	#include <c10/cuda/CUDAStream.h>
 16	#include <cuda_runtime.h>
 17	
 18	namespace {
 19	
 20	constexpr int kK = 2048;  // top-k width, const K of the problem definition
 21	constexpr int kBinBits = 8;
 22	constexpr int kBins = 1 << kBinBits;
 23	constexpr int kMask = kBins - 1;
 24	constexpr int kHistBlocks = 64;
 25	constexpr int kHistThreads = 256;
 26	constexpr int kGatherBlocks = 64;
 27	constexpr int kGatherThreads = 512;
 28	constexpr int kMaxWarps = kGatherThreads / 32;
 29	constexpr unsigned int kKeyMax = 0xFFFFFFFFu;
 30	constexpr unsigned int kNoBin = 0xFFFFFFFFu;
 31	
 32	// Per-row cross-launch state.
 33	struct __align__(16) RowSel {
 34	  unsigned int filter;  // cutoff key, low 8 bits cleared
 35	  int need;             // elements still required inside the cutoff bucket
 36	  int reserve_hi;       // scatter reservations for keys >= filter + kBins
 37	  int reserve_lo;       // scatter reservations inside the cutoff bucket
 38	};
 39	
 40	// Order-preserving float -> unsigned key map (bigger key == bigger float).
 41	__device__ __forceinline__ unsigned int mono_key(float value) {
 42	  const unsigned int bits = __float_as_uint(value);
 43	  return (bits & 0x80000000u) ? ~bits : (bits | 0x80000000u);
 44	}
 45	
 46	__device__ __forceinline__ float key_to_float(unsigned int key) {
 47	  const unsigned int bits = (key & 0x80000000u) ? (key & 0x7fffffffu) : ~key;
 48	  return __uint_as_float(bits);
 49	}
 50	
 51	// Locate the bucket holding the rank-th largest element (1-based rank) and count
 52	// the elements strictly above it. Results land in shared out[0]=digit, out[1]=above
 53	// because every thread needs them. Threads [0, kBins) drive the scan; every thread
 54	// must reach the barriers, so the guards stay inside the loop bodies.
 55	__device__ void locate_bucket(const int* __restrict__ hist, int rank, int* __restrict__ suff,
 56	                              int* __restrict__ out) {
 57	  const int tid = threadIdx.x;
 58	
 59	  // Reversed inclusive scan: suff[i] = sum of hist over buckets [kBins-1-i, kBins).
 60	  if (tid < kBins) suff[tid] = hist[kBins - 1 - tid];
 61	  __syncthreads();
 62	  for (int step = 1; step < kBins; step <<= 1) {
 63	    int value = 0;
 64	    int add = 0;
 65	    if (tid < kBins) {
 66	      value = suff[tid];
 67	      if (tid >= step) add = suff[tid - step];
 68	    }
 69	    __syncthreads();
 70	    if (tid < kBins) suff[tid] = value + add;
 71	    __syncthreads();
 72	  }
 73	
 74	  // Lowest index whose suffix sum reaches the rank marks the bucket.
 75	  const bool hit = (tid < kBins) && (suff[tid] >= rank);
 76	  const unsigned int ballot = __ballot_sync(0xFFFFFFFFu, hit);
 77	  __shared__ int s_first[kBins / 32];
 78	  if ((tid & 31) == 0 && (tid >> 5) < kBins / 32)
 79	    s_first[tid >> 5] = (ballot != 0) ? (__ffs(ballot) - 1) : -1;
 80	  __syncthreads();
 81	  if (tid == 0) {
 82	    int first = -1;
 83	    for (int warp = 0; warp < kBins / 32; ++warp) {
 84	      if (s_first[warp] >= 0) {
 85	        first = warp * 32 + s_first[warp];
 86	        break;
 87	      }
 88	    }
 89	    out[0] = (first >= 0) ? (kBins - 1 - first) : 0;
 90	    out[1] = (first > 0) ? suff[first - 1] : 0;
 91	  }
 92	  __syncthreads();
 93	}
 94	
 95	// One byte of the key per pass. LEVEL 1 histograms byte3 of the whole row, LEVEL 2
 96	// byte2 inside bucket byte3, LEVEL 3 byte1 inside bucket (byte3,byte2). The last
 97	// block to finish reduces the per-block slices and advances the cutoff.
 98	template <int LEVEL>
 99	__global__ void hist_pass(const float* __restrict__ values, int s, int chunk,
100	                          unsigned int* __restrict__ slices, RowSel* __restrict__ rows,
101	                          int* __restrict__ tickets) {
102	  __shared__ int bins[kBins];
103	  __shared__ int nz_bin[kBins];
104	  __shared__ int suff[kBins];
105	  __shared__ int s_locate[2];
106	  __shared__ int s_nz;
107	  __shared__ bool is_last;
108	
109	  for (int i = threadIdx.x; i < kBins; i += blockDim.x) bins[i] = 0;
110	  if (threadIdx.x == 0) s_nz = 0;
111	  __syncthreads();
112	
113	  const int row = blockIdx.y;
114	  const float* row_in = values + (size_t)row * s;
115	  RowSel* sel = rows + row;
116	  const int begin = blockIdx.x * chunk;
117	  const int end = min(begin + chunk, s);
118	  const int count = end - begin;
119	  const int shift = (LEVEL == 1) ? 24 : (LEVEL == 2) ? 16 : 8;
120	  const int upper = shift + kBinBits;
121	  const unsigned int prefix = (LEVEL == 1) ? 0u : (sel->filter >> upper);
122	  const unsigned int lane = threadIdx.x & 31u;
123	  const int iterations = (count + blockDim.x - 1) / blockDim.x;
124	
125	  // One shared atomic per distinct bin in a warp: clustered scores would otherwise
126	  // serialise 32 ways on the same address.
127	  for (int it = 0; it < iterations; ++it) {
128	    const int j = it * blockDim.x + threadIdx.x;
129	    unsigned int bin = kNoBin;
130	    if (j < count) {
131	      const unsigned int key = mono_key(row_in[begin + j]);
132	      if (LEVEL == 1 || ((key >> upper) == prefix)) bin = (key >> shift) & kMask;
133	    }
134	    const unsigned int match = __match_any_sync(0xFFFFFFFFu, bin);
135	    if (bin < kBins && (match & ((1u << lane) - 1u)) == 0) atomicAdd(&bins[bin], __popc(match));
136	  }
137	  __syncthreads();
138	
139	  // Compacted flush: only non-empty bins travel to global memory.
140	  if (threadIdx.x < kBins && bins[threadIdx.x] != 0) {
141	    const int slot = atomicAdd(&s_nz, 1);
142	    nz_bin[slot] = threadIdx.x;
143	  }
144	  __syncthreads();
145	  unsigned int* slice = slices + ((size_t)row * gridDim.x + blockIdx.x) * (1 + 2 * kBins);
146	  if (threadIdx.x == 0) slice[0] = (unsigned int)s_nz;
147	  for (int i = threadIdx.x; i < s_nz; i += blockDim.x) {
148	    const int bin = nz_bin[i];
149	    slice[1 + 2 * i] = (unsigned int)bin;
150	    slice[2 + 2 * i] = (unsigned int)bins[bin];
151	  }
152	  __threadfence();
153	  __syncthreads();
154	  if (threadIdx.x == 0) is_last = (atomicAdd(tickets + row, 1) == (int)gridDim.x - 1);
155	  __syncthreads();
156	  if (!is_last) return;
157	  __threadfence();
158	
159	  // Last block: rebuild the row histogram and advance the cutoff.
160	  for (int i = threadIdx.x; i < kBins; i += blockDim.x) bins[i] = 0;
161	  __syncthreads();
162	  for (int b = threadIdx.x; b < (int)gridDim.x; b += blockDim.x) {
163	    const unsigned int* other = slices + ((size_t)row * gridDim.x + b) * (1 + 2 * kBins);
164	    for (unsigned int i = 0; i < other[0]; ++i)
165	      atomicAdd(&bins[other[1 + 2 * i]], (int)other[2 + 2 * i]);
166	  }
167	  __syncthreads();
168	
169	  const int rank = (LEVEL == 1) ? kK : sel->need;
170	  locate_bucket(bins, rank, suff, s_locate);
171	
172	  if (threadIdx.x == 0) {
173	    sel->filter |= (unsigned int)s_locate[0] << shift;
174	    sel->need = (LEVEL == 1) ? (kK - s_locate[1]) : (sel->need - s_locate[1]);
175	    if (LEVEL == 3) {
176	      sel->reserve_hi = 0;
177	      sel->reserve_lo = 0;
178	    }
179	    tickets[row] = 0;  // ready for the next call
180	  }
181	}
