183	// Scatter: keys at or above the cutoff bucket (exact cutoff to 24 key bits) fill
184	// the tail of the row; everything above fills the head. Any need of the tail
185	// elements are interchangeable, so no ordering pass is required.
186	__global__ void gather_pass(const float* __restrict__ values, int s, int chunk,
187	                            RowSel* __restrict__ rows, float* __restrict__ out_values,
188	                            long long* __restrict__ out_idx) {
189	  __shared__ int s_warp_cnt[2][kMaxWarps];
190	  __shared__ int s_warp_off[2][kMaxWarps];
191	  __shared__ int s_res[2];
192	
193	  const int row = blockIdx.y;
194	  RowSel* sel = rows + row;
195	  const unsigned int filter = sel->filter;
196	  const unsigned int hi = (filter <= kKeyMax - kBins) ? (filter + kBins) : kKeyMax;
197	  const int head = kK - sel->need;  // slots for keys >= hi
198	  const float* row_in = values + (size_t)row * s;
199	  float* out_v = out_values + (size_t)row * kK;
200	  long long* out_i = out_idx + (size_t)row * kK;
201	  const int begin = blockIdx.x * chunk;
202	  const int end = min(begin + chunk, s);
203	  const int count = end - begin;
204	  const int lane = threadIdx.x & 31u;
205	  const int warp = threadIdx.x >> 5;
206	  const int iterations = (count + blockDim.x - 1) / blockDim.x;
207	
208	  // Pass 1: count this block's output slots so one reservation per region suffices.
209	  int cnt_hi = 0;
210	  int cnt_lo = 0;
211	  for (int it = 0; it < iterations; ++it) {
212	    const int j = it * blockDim.x + threadIdx.x;
213	    unsigned int key = 0;
214	    if (j < count) key = mono_key(row_in[begin + j]);
215	    const bool top = (j < count) && (key >= hi);
216	    const bool bucket = (j < count) && (key >= filter) && (key < hi);
217	    cnt_hi += __popc(__ballot_sync(0xFFFFFFFFu, top));
218	    cnt_lo += __popc(__ballot_sync(0xFFFFFFFFu, bucket));
219	  }
220	  if (lane == 0) {
221	    s_warp_cnt[0][warp] = cnt_hi;
222	    s_warp_cnt[1][warp] = cnt_lo;
223	  }
224	  __syncthreads();
225	  if (threadIdx.x == 0) {
226	    int off_hi = 0;
227	    int off_lo = 0;
228	    const int warps = (int)(blockDim.x >> 5);
229	    for (int w = 0; w < warps; ++w) {
230	      s_warp_off[0][w] = off_hi;
231	      s_warp_off[1][w] = off_lo;
232	      off_hi += s_warp_cnt[0][w];
233	      off_lo += s_warp_cnt[1][w];
234	    }
235	    s_res[0] = atomicAdd(&sel->reserve_hi, off_hi);
236	    s_res[1] = atomicAdd(&sel->reserve_lo, off_lo);
237	  }
238	  __syncthreads();
239	  const int base_hi = s_res[0] + s_warp_off[0][warp];
240	  const int base_lo = s_res[1] + s_warp_off[1][warp];
241	
242	  // Pass 2: write. Offsets repeat pass 1 exactly, so slots never collide.
243	  for (int it = 0; it < iterations; ++it) {
244	    const int j = it * blockDim.x + threadIdx.x;
245	    unsigned int key = 0;
246	    if (j < count) key = mono_key(row_in[begin + j]);
247	    const bool active = j < count;
248	    const bool top = active && (key >= hi);
249	    const bool bucket = active && (key >= filter) && (key < hi);
250	    const unsigned int m_top = __ballot_sync(0xFFFFFFFFu, top);
251	    const unsigned int m_bucket = __ballot_sync(0xFFFFFFFFu, bucket);
252	    if (top) {
253	      const int slot = base_hi + __popc(m_top & ((1u << lane) - 1u));
254	      if (slot < head) {
255	        out_v[slot] = key_to_float(key);
256	        out_i[slot] = (long long)(begin + j);
257	      }
258	    }
259	    if (bucket) {
260	      const int slot = head + base_lo + __popc(m_bucket & ((1u << lane) - 1u));
261	      if (slot < kK) {
262	        out_v[slot] = key_to_float(key);
263	        out_i[slot] = (long long)(begin + j);
264	      }
265	    }
266	  }
267	}
