270	// Host side
271	// ---------------------------------------------------------------------------
272	
273	void check_inputs(const torch::Tensor& values, const torch::Tensor& top_values,
274	                  const torch::Tensor& indices) {
275	  TORCH_CHECK_VALUE(values.is_cuda(), "values must be a CUDA tensor");
276	  TORCH_CHECK_TYPE(values.scalar_type() == torch::kFloat32, "values must be float32");
277	  TORCH_CHECK_VALUE(values.dim() == 2, "values must have shape [B, S]");
278	  TORCH_CHECK_VALUE(values.is_contiguous(), "values must be contiguous");
279	
280	  TORCH_CHECK_VALUE(top_values.is_cuda(), "top_values must be a CUDA tensor");
281	  TORCH_CHECK_TYPE(top_values.scalar_type() == torch::kFloat32, "top_values must be float32");
282	  TORCH_CHECK_VALUE(top_values.is_contiguous(), "top_values must be contiguous");
283	  TORCH_CHECK_TYPE(indices.scalar_type() == torch::kInt64, "indices must be int64");
284	  TORCH_CHECK_VALUE(indices.is_contiguous(), "indices must be contiguous");
285	
286	  const int64_t rows = values.size(0);
287	  const int64_t s = values.size(1);
288	  TORCH_CHECK_VALUE(s >= kK, "sequence length must be at least K");
289	  TORCH_CHECK_VALUE(top_values.dim() == 2 && top_values.size(0) == rows &&
290	                        top_values.size(1) == kK,
291	                    "top_values must have shape [B, K]");
292	  TORCH_CHECK_VALUE(indices.dim() == 2 && indices.size(0) == rows && indices.size(1) == kK,
293	                    "indices must have shape [B, K]");
294	  TORCH_CHECK_VALUE(top_values.device() == values.device() && indices.device() == values.device(),
295	                    "device mismatch");
296	  TORCH_CHECK_VALUE(s <= INT32_MAX, "sequence length too large");
297	  TORCH_CHECK_VALUE(rows <= INT32_MAX, "batch too large");
298	}
299	
300	// Persistent workspace: the kernels leave it zeroed across calls, so the steady
301	// state costs no allocation and no memset.
302	torch::Tensor& scratch(int device, int64_t rows) {
303	  static torch::Tensor buffer;
304	  static int64_t cached_rows = -1;
305	  static int cached_device = -1;
306	  if (!buffer.defined() || cached_rows != rows || cached_device != device) {
307	    const int64_t words = rows * kHistBlocks * (1 + 2 * kBins) + rows * 4 + rows * 3;
308	    buffer = torch::zeros({words}, torch::TensorOptions().dtype(torch::kInt32).device(
309	                                       torch::Device(torch::kCUDA, device)));
310	    cached_rows = rows;
311	    cached_device = device;
312	  }
313	  return buffer;
314	}
315	
316	void kernel(const torch::Tensor& values, const torch::Tensor& top_values,
317	            const torch::Tensor& indices) {
318	  check_inputs(values, top_values, indices);
319	  const int64_t rows = values.size(0);
320	  const int64_t s = values.size(1);
321	  if (rows == 0) return;
322	
323	  c10::cuda::CUDAGuard guard(values.device());
324	  const cudaStream_t stream = c10::cuda::getCurrentCUDAStream(values.get_device()).stream();
325	  torch::Tensor& workspace = scratch(values.get_device(), rows);
326	
327	  unsigned int* words = reinterpret_cast<unsigned int*>(workspace.data_ptr<int>());
328	  const size_t slice_words = (size_t)kHistBlocks * (1 + 2 * kBins);
329	  unsigned int* slices = words;
330	  RowSel* rows_sel = reinterpret_cast<RowSel*>(slices + (size_t)rows * slice_words);
331	  int* tickets = reinterpret_cast<int*>(rows_sel + rows);
