namespace {

constexpr int kK = 2048;
constexpr int kBlocks = 64;
constexpr int kThreads = 512;

__global__ void read_pass(const float* __restrict__ values, int s, int chunk,
                          float* __restrict__ out) {
  __shared__ float s_max[kThreads];
  const float* row = values + (size_t)blockIdx.y * s;
  const int begin = blockIdx.x * chunk;
  const int end = min(begin + chunk, s);
  float m = -1e30f;
  for (int j = begin + threadIdx.x; j < end; j += blockDim.x) m = fmaxf(m, row[j]);
  s_max[threadIdx.x] = m;
  __syncthreads();
  for (int st = kThreads / 2; st; st >>= 1) {
    if (threadIdx.x < st) s_max[threadIdx.x] = fmaxf(s_max[threadIdx.x], s_max[threadIdx.x + st]);
    __syncthreads();
  }
  if (threadIdx.x == 0 && s_max[0] > 1e30f) out[0] = s_max[0];
}

void kernel(const torch::Tensor& values, const torch::Tensor& top_values,
            const torch::Tensor& indices) {
  const int64_t s = values.size(1);
  const int64_t rows = values.size(0);
  const cudaStream_t stream = c10::cuda::getCurrentCUDAStream(values.get_device()).stream();
  const int chunk = (int)((s + kBlocks - 1) / kBlocks);
  const dim3 grid(kBlocks, (unsigned int)rows);
  read_pass<<<grid, kThreads, 0, stream>>>(values.data_ptr<float>(), (int)s, chunk,
                                           top_values.data_ptr<float>());
  cudaGetLastError();
}

}  // namespace

PYBIND11_MODULE(TORCH_EXTENSION_NAME, module) { module.def(\"kernel\", &kernel); }
